    if ((st == NULL) || (field == NULL) || (rate == NULL) || (cmd == NULL)) {
        return ADCS_E_NULL;
    }

    if ((!adcs_is_finite_vec3(field)) || (!isfinite(time)) || (!isfinite(alpha)) ||
        (!isfinite(gain)) || (!isfinite(limit))) {
        return ADCS_E_RANGE;
    }

    if ((alpha < 0.0) || (alpha > 1.0) || (gain < 0.0) || (limit < 0.0)) {
        return ADCS_E_RANGE;
    }

    if (st->initialized && (time <= st->previous_time_s)) {
        return ADCS_E_RANGE;
    }

    double b2 = adcs_vec3_dot(field, field);
    if (b2 <= ADCS_EPS_NORM * ADCS_EPS_NORM) {
        rate->x = 0.0; rate->y = 0.0; rate->z = 0.0;
        cmd->command.x = 0.0; cmd->command.y = 0.0; cmd->command.z = 0.0;
        cmd->saturated_axes = 0U;
        return ADCS_E_DEGENERATE;
    }

    adcs_status_t status = adcs_bdot_update(st, field, time, alpha, rate);
    if (status != ADCS_OK) {
        return status;
    }

    status = adcs_bdot_dipole(field, rate, gain, limit, cmd);
    if (status != ADCS_OK) {
        return status;
    }

    return ADCS_OK;
}

